function toggleSmsPanelFields() {
  const mode = document.getElementById('f-smsmode')?.value;
  const box = document.getElementById('sms-panel-fields');
  if (box) box.style.display = (mode === 'panel' || mode === 'both') ? 'block' : 'none';
}

function saveSchool(id) {
  const name = document.getElementById('f-name').value.trim();
  const code = document.getElementById('f-code').value.trim();
  const managerName = document.getElementById('f-manager').value.trim();
  const managerPhone = document.getElementById('f-phone').value.trim();
  const managerUsername = document.getElementById('f-muser').value.trim();
  const managerPassword = document.getElementById('f-mpass').value;
  if (!name || !code || !managerName || !managerPhone || !managerUsername || !managerPassword) {
    return toast('فیلدهای ستاره‌دار (از جمله کاربری و رمز مدیر) را پر کنید');
  }
  if (managerPassword.length < 6) {
    return toast('رمز مدیر حداقل ۶ کاراکتر باشد');
  }

  let modules = [...document.querySelectorAll('.mod-check:checked')].map(c => c.value);
  const dualChecked = modules.includes('dual_shift');
  let shifts = parseInt(document.getElementById('f-shifts').value, 10) || 1;
  // هر کدام دو شیفت را بگوید → دو شیفت
  if (dualChecked || shifts === 2) {
    shifts = 2;
    if (!modules.includes('dual_shift')) modules.push('dual_shift');
  } else {
    shifts = 1;
    modules = modules.filter(id => id !== 'dual_shift');
  }

  let plan = (document.getElementById('f-plan') && document.getElementById('f-plan').value) || 'paid';
  const expireDate = isoFromJalaliSelects('f-expire');
  let active = document.getElementById('f-active').checked;
  // اگر تاریخ انقضا معتبر است و کاربر فعال گذاشته → لایسنس زنده
  if (expireDate && expireDate >= todayStr() && active) {
    if (plan === 'trial' && id) {
      /* ویرایش آزمایشی مجاز */
    }
  }
  const data = {
    name,
    code,
    managerName,
    managerPhone,
    managerUsername,
    managerPassword,
    city: document.getElementById('f-city').value.trim(),
    notes: document.getElementById('f-notes').value.trim(),
    startDate: isoFromJalaliSelects('f-start'),
    expireDate,
    maxUsers: parseInt(document.getElementById('f-maxusers').value) || 20,
    shifts,
    modules,
    smsMode: document.getElementById('f-smsmode').value,
    smsApiUrl: document.getElementById('f-apiurl')?.value.trim() || '',
    smsApiUser: document.getElementById('f-apiuser')?.value.trim() || '',
    smsApiKey: document.getElementById('f-apikey')?.value.trim() || '',
    smsSender: document.getElementById('f-sender')?.value.trim() || '',
    active,
    plan
  };

  if (id) {
    const s = state.schools.find(x => x.id === id);
    if (!s) return;
    // تمدید: تاریخ جدید + فعال = رسمی مگر خودت آزمایشی بگذاری
    if (data.expireDate && data.expireDate >= todayStr() && data.active && data.plan !== 'trial') {
      data.plan = 'paid';
    }
    Object.assign(s, data);
    s.updatedAtMs = Date.now();
  } else {
    if (state.schools.some(x => x.code === code)) return toast('این کد مدرسه تکراری است');
    state.schools.push({
      id: uid(),
      ...data,
      activationCode: genActivationCode(),
      activationUsed: false,
      createdAt: todayStr(),
      plan: data.plan || 'paid',
      source: 'mother',
      _neverSynced: true,
      updatedAtMs: Date.now()
    });
  }
  // مدرسه جدید تا ارسال موفق به سرور، فقط-محلی بماند تا با pull پاک نشود
  const saved = id ? state.schools.find(function (x) { return x.id === id; }) : state.schools[state.schools.length - 1];
  if (saved) {
    if (!id) saved._neverSynced = true;
    saved.updatedAtMs = Date.now();
  }
  save();
  closeModal();
  renderSchools();
  renderDashboard();
  toast('در حال ارسال به سرور...');
  if (saved) {
    cloudPushOneSchool(saved).then(function (ok) {
      if (ok) {
        saved._neverSynced = false;
        saved._synced = true;
        saved._pushed = true;
        save();
        toast('ذخیره شد و روی همه دستگاه‌ها می‌آید ✓');
      } else {
        // اگر ارسال شکست خورد، محلی نگه دار تا pull بعدی پاکش نکند
        saved._neverSynced = true;
        save();
        toast('محلی ذخیره شد — اتصال سرور برقرار نشد؛ دوباره «ارسال همه» را بزنید');
      }
    });
  }
}

async function deleteSchool(id) {
  if (!confirm('حذف کامل این مدرسه از پنل مادر و سرور؟')) return;
  const removed = (state.schools || []).find(x => x.id === id);
  state.schools = state.schools.filter(x => x.id !== id);
  save();
  closeModal();
  renderSchools();
  renderDashboard();
  toast('در حال حذف از سرور...');
  try {
    if (SYNC_API && id) {
      await apiFetch('/api/schools/' + encodeURIComponent(id), { method: 'DELETE', retries: 3 });
    }
    toast('حذف شد (این دستگاه + سرور)');
    // بلافاصله دوباره از سرور بگیر تا همه دستگاه‌ها یکدست شوند
    await cloudPullSchools();
    renderSchools();
    renderDashboard();
  } catch (e) {
    // اگر حذف سرور شکست خورد، مدرسه را برنگردان — فقط هشدار بده تا دوباره تلاش شود
    toast('از این دستگاه حذف شد؛ سرور خطا داد — «ارسال همه» یا دوباره حذف را بزنید: ' + (e.message || e));
    console.error(e);
  }
}

function closeModal() {
  document.getElementById('modal').classList.remove('show');
}
document.getElementById('modal').addEventListener('click', e => {
  if (e.target.id === 'modal') closeModal();
});

/* Settings */
function changeMotherAccount() {
  const cur = document.getElementById('cur-pass').value;
  const n1 = document.getElementById('new-pass').value;
  const n2 = document.getElementById('new-pass2').value;
  const newUser = (document.getElementById('mother-user-new').value || '').trim();
  if (cur !== state.motherPass) return toast('رمز فعلی اشتباه است');
  if (newUser) {
    if (newUser.length < 3) return toast('نام کاربری حداقل ۳ کاراکتر');
    state.motherUser = newUser;
  }
  if (n1) {
    if (n1.length < 6) return toast('رمز جدید حداقل ۶ کاراکتر');
    if (n1 !== n2) return toast('تکرار رمز یکسان نیست');
    state.motherPass = n1;
  }
  if (!newUser && !n1) return toast('نام کاربری یا رمز جدید را وارد کنید');
  save();
  document.getElementById('cur-pass').value = '';
  document.getElementById('new-pass').value = '';
  document.getElementById('new-pass2').value = '';
  document.getElementById('mother-user-new').value = '';
  const disp = document.getElementById('mother-user-display');
  if (disp) disp.value = state.motherUser;
  toast('حساب پنل مادر به‌روز شد');
}
function changeMotherPassword(){ changeMotherAccount(); }
function fillMotherAccountForm(){
  const disp = document.getElementById('mother-user-display');
  if (disp) disp.value = state.motherUser || 'admin';
}

function downloadJsonFile(obj, filename) {
  const blob = new Blob([JSON.stringify(obj, null, 2)], { type: 'application/json;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  setTimeout(function () { try { URL.revokeObjectURL(a.href); } catch (e) {} }, 2000);
}
async function fetchSchoolAppData(schoolId) {
  if (!SYNC_API || !schoolId) return null;
  try {
    const data = await apiFetch('/api/schools/' + encodeURIComponent(schoolId) + '/appData', { retries: 1 });
    return (data && data.data) ? data.data : null;
  } catch (e) {
    return null;
  }
}
async function fetchSchoolSubmissions(schoolId) {
  if (!SYNC_API || !schoolId) return [];
  try {
    const data = await apiFetch('/api/schools/' + encodeURIComponent(schoolId) + '/submissions', { retries: 1 });
    return (data && Array.isArray(data.submissions)) ? data.submissions : [];
  } catch (e) {
    return [];
  }
}
async function fetchCompleteSchoolPackage(school) {
  if (!school || !school.id) return { school: school, appData: null, submissions: [] };
  const appData = await fetchSchoolAppData(school.id);
  const submissions = await fetchSchoolSubmissions(school.id);
  let full = appData ? Object.assign({}, appData) : null;
  if (submissions && submissions.length) {
    if (!full) full = {};
    const map = {};
    (full.submissions || []).forEach(function (s) { if (s && s.id) map[s.id] = s; });
    submissions.forEach(function (s) { if (s && s.id) map[s.id] = s; });
    full.submissions = Object.keys(map).map(function (k) { return map[k]; });
  }
  return { school: school, appData: full, submissions: submissions || [] };
}
async function exportOneSchoolFullBackup(id) {
  const s = (state.schools || []).find(function (x) { return x.id === id; });
  if (!s) return toast('مدرسه یافت نشد');
  toast('در حال دریافت پشتیبان کامل مدرسه از سرور...');
  const pack = await fetchCompleteSchoolPackage(s);
  const appData = pack.appData;
  const payload = {
    type: 'nikan-school-backup',
    version: 2,
    complete: true,
    exportedAt: new Date().toISOString(),
    school: s,
    appData: appData,
    submissions: pack.submissions || [],
    summary: {
      classes: appData && appData.classes ? appData.classes.length : 0,
      students: appData && appData.students ? appData.students.length : 0,
      staff: appData && appData.staff ? appData.staff.length : 0,
      attendance: appData && appData.attendance ? appData.attendance.length : 0,
      assignments: appData && appData.assignments ? appData.assignments.length : 0,
      exams: appData && appData.exams ? appData.exams.length : 0,
      messages: appData && appData.messages ? appData.messages.length : 0,
      submissions: (pack.submissions || []).length
    },
    note: appData ? 'پشتیبان کامل صفر تا صد' : 'فقط لایسنس — از پنل مدرسه هم پشتیبان کامل بگیرید'
  };
  const safeName = String(s.code || s.name || id).replace(/[^\\\\w\\\\u0600-\\\\u06FF\\\\-]+/g, '_');
  downloadJsonFile(payload, 'school-FULL-backup-' + safeName + '-' + todayStr() + '.json');
  toast(appData ? ('پشتیبان کامل · کلاس: ' + payload.summary.classes + ' · دانش‌آموز: ' + payload.summary.students) : 'لایسنس ذخیره شد (داده سرور خالی/قطع بود)');
}
async function exportAllSchoolsFullBackup() {
  const list = state.schools || [];
  if (!list.length) return toast('مدرسه‌ای نیست');
  toast('در حال تهیه پشتیبان کامل همه مدارس...');
  const items = [];
  for (let i = 0; i < list.length; i++) {
    items.push(await fetchCompleteSchoolPackage(list[i]));
  }
  const payload = {
    type: 'nikan-mother-schools-full-backup',
    version: 2,
    complete: true,
    exportedAt: new Date().toISOString(),
    schoolsCount: items.length,
    withAppData: items.filter(function (x) { return !!x.appData; }).length,
    motherUser: state.motherUser || 'admin',
    items: items
  };
  downloadJsonFile(payload, 'nikan-ALL-schools-FULL-backup-' + todayStr() + '.json');
  toast('پشتیبان کامل: ' + payload.schoolsCount + ' مدرسه · با داده: ' + payload.withAppData);
}
function exportMotherData() {
  const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'nikan-mother-licenses-backup-' + todayStr() + '.json';
  a.click();
  toast('دانلود شد');
}

async function cloudPushAppDataForSchool(schoolId, appData) {
  if (!SYNC_API || !schoolId || !appData || typeof appData !== 'object') return false;
  try {
    const payload = Object.assign({}, appData, { updatedAtMs: Date.now() });
    await apiFetch('/api/schools/' + encodeURIComponent(schoolId) + '/appData', {
      method: 'PUT',
      body: payload,
      retries: 2
    });
    return true;
  } catch (e) {
    console.warn('cloudPushAppDataForSchool', e);
    return false;
  }
}

function mergeSchoolIntoState(school) {
  if (!school || !school.id) return;
  if (!state.schools) state.schools = [];
  const i = state.schools.findIndex(function (x) { return x.id === school.id || (school.code && x.code === school.code); });
  if (i >= 0) state.schools[i] = Object.assign({}, state.schools[i], school);
  else state.schools.push(school);
}

async function restoreBackupItems(items) {
  let okSchool = 0, okData = 0, fail = 0, localOnly = 0;
  for (let i = 0; i < items.length; i++) {
    try {
      const it = items[i] || {};
      const school = it.school || it;
      let appData = it.appData ? Object.assign({}, it.appData) : null;
      if (!school || !school.id) { fail++; continue; }
      // ادغام لایسنس در پنل مادر (حتی اگر سرور قطع باشد)
      mergeSchoolIntoState(school);
      const pushed = await cloudPushOneSchool(school);
      if (pushed) okSchool++;
      else { localOnly++; }
      if (appData || (it.submissions && it.submissions.length)) {
        if (!appData) appData = {};
        if (it.submissions && it.submissions.length) {
          if (!appData.submissions) appData.submissions = [];
          const map = {};
          appData.submissions.forEach(function (s) { if (s && s.id) map[s.id] = s; });
          it.submissions.forEach(function (s) { if (s && s.id) map[s.id] = s; });
          appData.submissions = Object.keys(map).map(function (k) { return map[k]; });
        }
        const dOk = await cloudPushAppDataForSchool(school.id, appData);
        if (dOk) okData++;
        if (appData.submissions && appData.submissions.length && SYNC_API) {
          for (let j = 0; j < Math.min(appData.submissions.length, 200); j++) {
            try {
              await apiFetch('/api/schools/' + encodeURIComponent(school.id) + '/submissions', {
                method: 'POST',
                body: appData.submissions[j],
                retries: 1
              });
            } catch (e) {}
          }
        }
      }
    } catch (e) {
      console.error('restore item', e);
      fail++;
    }
  }
  save();
  try { renderDashboard(); renderSchools(); } catch (e) {}
  return { okSchool: okSchool, okData: okData, fail: fail, localOnly: localOnly };
}

function importMotherData(ev) {
  const file = ev.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = async function () {
    try {
      const data = JSON.parse(reader.result);
      let items = [];
      // پشتیبان کامل همه مدارس
      if (data.type === 'nikan-mother-schools-full-backup' && Array.isArray(data.items)) {
        items = data.items;
      }
      // پشتیبان تک‌مدرسه
      else if (data.type === 'nikan-school-backup' && data.school) {
        items = [{ school: data.school, appData: data.appData || null, submissions: data.submissions || [] }];
      }
      // فرمت قدیمی فقط لیست لایسنس
      else if (Array.isArray(data.schools)) {
        items = data.schools.map(function (s) { return { school: s, appData: null }; });
      } else {
        throw new Error('invalid');
      }
      if (!items.length) throw new Error('empty');
      const msg = 'تعداد ' + items.length + ' مورد از فایل خوانده شد.\\\\nلایسنس‌ها در پنل مادر ادغام و روی سرور ارسال می‌شوند.\\\\nاگر فایل پشتیبان کامل باشد، داده کلاس/دانش‌آموز هم برمی‌گردد.\\\\nادامه؟';
      if (!confirm(msg)) return;
      toast('در حال بازیابی روی سرور...');
      const r = await restoreBackupItems(items);
      toast('بازیابی: لایسنس سرور ' + r.okSchool + ' · داده ' + r.okData + (r.localOnly ? ' · فقط محلی ' + r.localOnly : '') + (r.fail ? ' · خطا ' + r.fail : ''));
    } catch (e) {
      toast('فایل نامعتبر است یا خوانده نشد');
    }
  };
  reader.readAsText(file);
  ev.target.value = '';
}

/* همگام خودکار بین دستگاه‌ها */
let _motherPullTimer = null, _motherPullBusy = false;
function startMotherAutoSync() {
  clearInterval(_motherPullTimer);
  const base = 90000 + Math.floor(Math.random() * 30000);
  _motherPullTimer = setInterval(function () {
    if (document.hidden) return;
    if (document.getElementById('app').style.display === 'none') return;
    motherAutoPull();
  }, base);
}
async function motherAutoPull() {
  if (_motherPullBusy) return;
  _motherPullBusy = true;
  try {
    const ok = await cloudPullSchools();
    if (ok) {
      try { renderDashboard(); renderSchools(); } catch (e) {}
    }
  } catch (e) {}
  finally { _motherPullBusy = false; }
}
document.addEventListener('visibilitychange', function () {
  if (!document.hidden && document.getElementById('app').style.display !== 'none') motherAutoPull();
});


function openMotherRecovery(){
  var box=document.getElementById('recovery-box');
  if(box){
    box.style.display='block';
    try{ box.scrollIntoView({behavior:'smooth',block:'nearest'}); }catch(e){}
  }
  try{
    var hint=document.getElementById('login-hint');
    if(hint) hint.innerHTML='بازیابی: کد مدرسه <b>SCH-7060</b> و کاربری/رمز <b>مدیر همان مدرسه</b> را بزنید.';
  }catch(e){}
}
function closeMotherRecovery(){
  var box=document.getElementById('recovery-box');
  if(box) box.style.display='none';
}
async function doMotherRecovery(){
  var code=String((document.getElementById('rec-school')||{}).value||'').trim();
  var user=String((document.getElementById('rec-user')||{}).value||'').trim();
  var pass=String((document.getElementById('rec-pass')||{}).value||'').trim();
  var nu=String((document.getElementById('rec-new-user')||{}).value||'').trim()||'admin';
  var np=String((document.getElementById('rec-new-pass')||{}).value||'').trim();
  if(!code||!user||!pass) return toast('کد مدرسه و کاربری/رمز مدیر لازم است');
  if(np.length<6) return toast('رمز جدید مادر حداقل ۶ کاراکتر');
  toast('در حال بررسی از سرور...');
  try{
    const data = await apiFetch('/api/schools', { retries: 2, timeoutMs: 25000 });
    const schools = (data && data.schools) || [];
    const codeN = code.toUpperCase().split(' ').join('');
    let found = null;
    for(let i=0;i<schools.length;i++){
      const s=schools[i];
      if(!s) continue;
      const sc=String(s.code||'').toUpperCase();
      const sn=String(s.name||'');
      if(sc===codeN || sc.indexOf(codeN)>=0 || sn.indexOf(code)>=0){ found=s; break; }
    }
    if(!found) return toast('مدرسه روی سرور پیدا نشد');
    const mu=String(found.managerUsername||'').trim();
    const mp=String(found.managerPassword||'').trim();
    function norm(x){
      var s = String(x || '').trim();
      var fa = '۰۱۲۳۴۵۶۷۸۹';
      var ar = '٠١٢٣٤٥٦٧٨٩';
      var out = '';
      for (var i = 0; i < s.length; i++) {
        var ch = s.charAt(i);
        var fi = fa.indexOf(ch);
        if (fi >= 0) { out += String(fi); continue; }
        var ai = ar.indexOf(ch);
        if (ai >= 0) { out += String(ai); continue; }
        out += ch;
      }
      return out;
    }
    if(norm(mu)!==norm(user) || norm(mp)!==norm(pass)){
      return toast('نام کاربری یا رمز مدیر این مدرسه اشتباه است');
    }
    // تأیید شد — بازنشانی حساب مادر
    state.motherUser = nu;
    state.motherPass = np;
    save();
    // مدارس را هم از سرور بگیر
    state.schools = schools.map(function(s){ return Object.assign({}, s, { _synced:true, _pushed:true }); });
    save();
    try{ document.getElementById('login-user').value = nu; }catch(e){}
    closeMotherRecovery();
    toast('حساب مادر بازنشانی شد — با نام کاربری و رمز جدید وارد شوید');
    try{ renderDashboard(); renderSchools(); }catch(e){}
  }catch(e){
    console.warn(e);
    toast('ارتباط با سرور برقرار نشد — فیلترشکن/اینترنت را چک کنید');
  }
}


