function brandIsImageFile(file){
  if(!file) return false;
  var typ = String(file.type || '').toLowerCase();
  if(typ.indexOf('image/') === 0) return true;
  var name = String(file.name || '').toLowerCase();
  return /\\.(jpe?g|png|gif|webp|jfif|bmp|svg)$/i.test(name);
}

function brandReadFileAsDataURL(file){
  return new Promise(function(resolve, reject){
    var reader = new FileReader();
    reader.onload = function(){ resolve(reader.result); };
    reader.onerror = function(){ reject(new Error('read_failed')); };
    reader.readAsDataURL(file);
  });
}

function brandLoadImage(src){
  return new Promise(function(resolve, reject){
    var img = new Image();
    img.onload = function(){ resolve(img); };
    img.onerror = function(){ reject(new Error('img_failed')); };
    img.src = src;
  });
}

async function brandMakeSquareLogo(file){
  var dataUrl = await brandReadFileAsDataURL(file);
  var img = await brandLoadImage(dataUrl);
  var side = Math.min(img.width, img.height) || 1;
  var sx = Math.floor((img.width - side) / 2);
  var sy = Math.floor((img.height - side) / 2);
  var size = 256;
  var canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  var ctx = canvas.getContext('2d');
  ctx.fillStyle = '#0b1220';
  ctx.fillRect(0, 0, size, size);
  ctx.drawImage(img, sx, sy, side, side, 0, 0, size, size);
  var out = canvas.toDataURL('image/jpeg', 0.85);
  if(out.length > 400000) out = canvas.toDataURL('image/jpeg', 0.7);
  return out;
}

async function brandMakeBg(file){
  var dataUrl = await brandReadFileAsDataURL(file);
  var img = await brandLoadImage(dataUrl);
  var maxSide = 1280;
  var w = img.width || 1;
  var h = img.height || 1;
  var scale = Math.min(1, maxSide / Math.max(w, h));
  w = Math.max(1, Math.round(w * scale));
  h = Math.max(1, Math.round(h * scale));
  var canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  canvas.getContext('2d').drawImage(img, 0, 0, w, h);
  var out = canvas.toDataURL('image/jpeg', 0.75);
  if(out.length > 800000) out = canvas.toDataURL('image/jpeg', 0.55);
  return out;
}

