function shrinkStaffPhotoDataUrl(dataUrl, maxW, quality){
  maxW=maxW||160;quality=quality||0.72;
  return new Promise(function(resolve){
    try{
      if(!dataUrl||String(dataUrl).indexOf('data:image')!==0){resolve(dataUrl||'');return}
      if(String(dataUrl).length<20000){resolve(dataUrl);return}
      var img=new Image();
      img.onload=function(){
        try{
          var scale=Math.min(1,maxW/Math.max(img.width,1));
          var c=document.createElement('canvas');
          c.width=Math.max(1,Math.round(img.width*scale));
          c.height=Math.max(1,Math.round(img.height*scale));
          c.getContext('2d').drawImage(img,0,0,c.width,c.height);
          resolve(c.toDataURL('image/jpeg',quality));
        }catch(e){resolve(dataUrl)}
      };
      img.onerror=function(){resolve(dataUrl)};
      img.src=dataUrl;
    }catch(e){resolve(dataUrl||'')}
  });
}
async function pushOneStaffMember(member){
  if(!SYNC_API||!session||!session.schoolId||!member||!member.id)return false;
  if(!isManager())return false;
  var m=Object.assign({},member);
  if(m.photo){
    try{m.photo=await shrinkStaffPhotoDataUrl(m.photo,140,0.68)}catch(e){}
  }
  // فقط فیلدهای لازم این یک نفر
  var one={
    id:String(m.id),
    name:m.name||'',
    role:m.role||'teacher',
    username:m.username||'',
    pass:m.pass||m.password||'',
    phone:m.phone||'',
    shift:(m.shift===0||m.shift)?m.shift:null,
    active:m.active!==false
  };
  if(m.photo)one.photo=m.photo;
  var body={
    _staffOnly:true,
    staff:[one],
    managerAuthority:true,
    _teacherPartial:true,
    _compatNoAuth:true,
    auth:{
      user:(schoolData&&(schoolData.managerUser||schoolData.managerUsername))||(userSession&&userSession.username)||'',
      pass:(schoolData&&schoolData.managerPass)||(userSession&&userSession.pass)||'',
      role:'manager'
    }
  };
  try{
    await apiFetch('/api/schools/'+encodeURIComponent(session.schoolId)+'/appData/teacher',{
      method:'POST',body:body,retries:1,timeoutMs:25000
    });
    if(one.photo){
      try{await pushStaffSelfUpdate({id:String(one.id),photo:one.photo})}catch(e2){}
    }
    return true;
  }catch(e){
    console.warn('pushOneStaffMember teacher',e);
    // مسیر جایگزین: appData اصلی فقط با همین یک نفر
    try{
      await apiFetch('/api/schools/'+encodeURIComponent(session.schoolId)+'/appData',{
        method:'PUT',
        body:{
          _staffOnly:true,
          staff:[one],
          managerAuthority:true,
          _softOnly:true,
          _compatNoAuth:true,
          updatedAtMs:Date.now()
        },
        retries:1,
        timeoutMs:25000
      });
      return true;
    }catch(e2){
      console.warn('pushOneStaffMember appData',e2);
      if(one.photo){
        try{return !!(await pushStaffSelfUpdate({id:String(one.id),photo:one.photo}))}catch(e3){return false}
      }
      return false;
    }
  }
}

function saveStaff(id){
  if(!isManager())return toast('فقط مدیر');
  try{
    const nameEl=document.getElementById('st-name');
    const roleEl=document.getElementById('st-role');
    const userEl=document.getElementById('st-user');
    const passEl=document.getElementById('st-pass');
    const phoneEl=document.getElementById('st-phone');
    if(!nameEl||!roleEl||!userEl||!passEl){
      return toast('فرم کاربر آماده نیست — صفحه را رفرش کنید');
    }
    const name=nameEl.value.trim();
    const role=roleEl.value||'teacher';
    const username=normLoginUser(userEl.value.trim());
    const pass=String(passEl.value||'');
    const phone=fixPhone(phoneEl?phoneEl.value:'');
    const shiftRaw=document.getElementById('st-shift')?document.getElementById('st-shift').value:'';
    const shift=shiftRaw===''?null:parseInt(shiftRaw,10);
    if(!name||!username||!pass)return toast('نام، کاربری و رمز لازم است');
    if(pass.length<4)return toast('رمز حداقل ۴ کاراکتر باشد');
    if(!schoolData)loadSchoolData();
    if(!Array.isArray(schoolData.staff))schoolData.staff=[];
    // جلوگیری از نام کاربری تکراری
    const dup=schoolData.staff.find(function(x){return x && String(x.username||'')===String(username) && (!id || x.id!==id);});
    if(dup)return toast('این نام کاربری قبلاً برای «'+(dup.name||'')+'» ثبت شده');
    // شیفت کاربر فقط وقتی لایسنس دو شیفت دارد معنا دارد
    if(!dualShift()){/* ignore local force */}
    else schoolData.shifts=2;
    var photo=(typeof window._pendingPhoto!=='undefined' && window._pendingPhoto!==null)?window._pendingPhoto:'';
    // فشرده سریع عکس تیم قبل از ذخیره (۱۶۰px)
    if(photo&&String(photo).indexOf('data:image')===0&&String(photo).length>25000){
      try{
        // تقریبی: اگر خیلی بزرگ است در لحظه نمی‌کشیم؛ در push جداگانه کوچک می‌شود
      }catch(e){}
    }
    if(id){
      const u=schoolData.staff.find(x=>x.id===id);
      if(u){
        u.name=name;u.role=role;u.username=username;u.pass=pass;u.phone=phone;u.shift=shift;u.active=true;
        if(photo!==''||photo==='')u.photo=photo||'';
        if(userSession&&userSession.staffId===u.id){userSession.photo=u.photo||'';userSession.name=u.name;saveUserSession(userSession)}
      }else{
        return toast('کاربر برای ویرایش یافت نشد');
      }
    }else{
      schoolData.staff.push({id:uid(),name:name,role:role,username:username,pass:pass,phone:phone,shift:shift,photo:photo||'',active:true});
    }
    schoolData._cloudUpdatedAtMs=Date.now();
    schoolData._localDirtyAt=Date.now();
    if(canManage()){
      markIntentionalSave('structure');
    }
    saveSchoolData();
    closeModal();
    try{renderTeam();}catch(e){}
    toast('ذخیره شد — فقط همین کاربر به سرور می‌رود...');
    if(session&&session.schoolId&&isManager()){
      (async function(){
        try{
          var _sid=id||'';
          if(!_sid){
            try{_sid=((schoolData.staff||[])[(schoolData.staff||[]).length-1]||{}).id||''}catch(e){}
          }
          var _st=(schoolData.staff||[]).find(function(x){return x&&String(x.id)===String(_sid)});
          if(!_st){
            toast('کاربر محلی ذخیره شد');
            return;
          }
          // فقط همین یک نفر — نه کل تیم، نه کل appData
          var ok=await pushOneStaffMember(_st);
          toast(ok?'✓ همین کاربر روی سرور ذخیره شد':'⚠ محلی ماند؛ اینترنت را چک کنید و دوباره ذخیره کنید',ok?3000:5000);
        }catch(e){
          console.warn('saveStaff push',e);
          toast('محلی ذخیره شد؛ ارسال سرور ناموفق',5000);
        }
        try{
          schoolData.replaceStructure=false;
          schoolData._structureWriteToken=false;
          saveSchoolData();
        }catch(e){}
      })();
    }
  }catch(err){
    console.error('saveStaff',err);
    toast('خطا در ذخیره کاربر: '+(err&&err.message?err.message:err));
  }
}
