  var cOpts=(schoolData.classes||[]).map(function(c){return '<option value="'+c.id+'"'+(a&&a.classId===c.id?' selected':'')+'>'+(typeof classTitle==='function'?classTitle(c):(c.name||c.id))+'</option>'}).join('');
