  document.getElementById('modal-body').innerHTML=
    '<p class="hint" style="margin-bottom:10px">یک <b>درس</b> می‌تواند چند <b>زنگ</b> در هفته داشته باشد (همان نام درس را تکرار کنید). هر زنگ حضورغیاب جدا دارد.</p>'+
    '<div class="form-group"><label>جستجوی معلم</label><input class="form-control" id="as-teacher-search" placeholder="نام معلم..." oninput="filterAssignTeacherSelect()" /></div>'+
    '<div class="form-group"><label>معلم اصلی *</label><select class="form-control" id="as-teacher">'+tOpts+'</select></div>'+
    '<div class="form-group"><label>معلم دوم (اختیاری — هر دو معلم به کلاس دسترسی دارند؛ گروه فقط اگر کلاس دو قسمتی است)</label><select class="form-control" id="as-teacher2">'+t2Opts+'</select></div>'+
    '<div class="form-group"><label>کلاس *</label><select class="form-control" id="as-class">'+cOpts+'</select></div>'+
    '<div class="form-group"><label>گروه کلاس</label><select class="form-control" id="as-group">'+
      '<option value=""'+(!g?' selected':'')+'>همه دانش‌آموزان کلاس (پیشنهادی برای معلم دوم)</option>'+
      '<option value="الف"'+(g==='الف'||g==='1'?' selected':'')+'>گروه الف</option>'+
      '<option value="ب"'+(g==='ب'||g==='2'?' selected':'')+'>گروه ب</option>'+
    '</select><p class="hint">برای تقسیم کلاس: یک زنگ با گروه الف + یک زنگ با گروه ب (همان ساعت/درس)</p></div>'+
    '<div class="form-group"><label>نام درس *</label><input class="form-control" id="as-subject" value="'+(a&&a.subject?a.subject:'')+'" placeholder="مثلاً ریاضی — در همه زنگ‌های این درس یکسان بنویسید" /></div>'+
    '<div class="form-group"><label>روز هفته</label><select class="form-control" id="as-day">'+dOpts+'</select></div>'+
    '<div class="form-group"><label>عنوان زنگ</label><input class="form-control" id="as-period" value="'+(a&&a.periodName?a.periodName:'زنگ ۱')+'" placeholder="زنگ ۱ یا زنگ 1-2" /></div>'+
    '<div class="form-group"><label>از ساعت</label><input class="form-control" id="as-start" type="time" value="'+(a&&a.startTime?a.startTime:'08:00')+'" /></div>'+
    '<div class="form-group"><label>تا ساعت</label><input class="form-control" id="as-end" type="time" value="'+(a&&a.endTime?a.endTime:'09:30')+'" /></div>'+
    '<button type="button" class="btn btn-primary btn-block" data-id="'+idStr+'" onclick="saveAssign(this.dataset.id||null)">ذخیره</button>';
