    h+='<button type="button" class="qa-item" onclick="openContactSalesModal()"><span class="ic">🤝</span><span class="lb">پشتیبانی</span><span class="ds">تماس و شبکه‌های اجتماعی</span></button>';
    hub.innerHTML=h;
