  brandSetVal('brand-ad', d.ad);
  brandSetVal('brand-ad-link', d.adLink);
  brandSetVal('brand-bg', d.bg || '#070b14');
  brandSetVal('brand-accent', d.accent || '#38bdf8');
  brandSetVal('brand-text', d.text || '#e8eef7');
  brandSetVal('brand-card', d.card || '#111a2e');
  brandSetVal('brand-font', d.font || 'Tahoma, sans-serif');
  brandSetVal('brand-title-size', d.titleSize || '1.65rem');
  brandSetVal('brand-body-size', d.bodySize || '14.5px');
  var ov = document.getElementById('brand-bg-overlay');
  if(ov) ov.value = d.bgOverlay != null ? d.bgOverlay : 55;
  var ovv = document.getElementById('brand-bg-ov-val');
  if(ovv) ovv.textContent = (d.bgOverlay != null ? d.bgOverlay : 55) + '%';
  brandSetChk('brand-enabled', d.enabled !== false);
