function collectBrandForm(){
  var fTitle = brandGetVal('brand-font-title') || brandGetVal('brand-font') || 'Tahoma, sans-serif';
  var fSub = brandGetVal('brand-font-subtitle') || brandGetVal('brand-font') || 'Tahoma, sans-serif';
  var fBody = brandGetVal('brand-font-body') || brandGetVal('brand-font') || 'Tahoma, sans-serif';
  var fAnn = brandGetVal('brand-font-announce') || brandGetVal('brand-font') || 'Tahoma, sans-serif';
  return {
    logo: window._brandLogoData || '',
    bgImage: window._brandBgData || '',
    enabled: brandGetChk('brand-enabled'),
    title: String(brandGetVal('brand-title') || '').trim().slice(0, 80),
    subtitle: String(brandGetVal('brand-subtitle') || '').trim().slice(0, 120),
    announce: String(brandGetVal('brand-announce') || '').trim().slice(0, 300),
    ad: String(brandGetVal('brand-ad') || '').trim().slice(0, 400),
    adLink: String(brandGetVal('brand-ad-link') || '').trim().slice(0, 300),
    bg: brandGetVal('brand-bg') || '#070b14',
    accent: brandGetVal('brand-accent') || '#38bdf8',
    text: brandGetVal('brand-text') || '#e8eef7',
    card: brandGetVal('brand-card') || '#111a2e',
    font: fBody,
    fontTitle: fTitle,
    fontSubtitle: fSub,
    fontBody: fBody,
    fontAnnounce: fAnn,
    titleSize: brandGetVal('brand-title-size') || '1.65rem',
    bodySize: brandGetVal('brand-body-size') || '14.5px',
    bgOverlay: parseInt(brandGetVal('brand-bg-overlay'), 10) || 55
  };
}




window._nikanFontLinks = window._nikanFontLinks || {};
function ensureNikanBrandFonts(fontFamily){
  try{
    var ff = String(fontFamily || '');
    // accept multiple fonts joined
    if(arguments.length > 1){ for(var ai=1;ai<arguments.length;ai++) ff += ' ' + String(arguments[ai]||''); }
    var links = [];
    if(/Vazirmatn/i.test(ff)) links.push({id:'nf-vazir', href:'https://cdn.jsdelivr.net/gh/rastikerdar/vazirmatn@v33.003/Vazirmatn-font-face.css'});
    if(/Samim/i.test(ff)) links.push({id:'nf-samim', href:'https://cdn.jsdelivr.net/gh/rastikerdar/samim-font@v4.0.5/dist/font-face.css'});
    if(/Shabnam/i.test(ff)) links.push({id:'nf-shabnam', href:'https://cdn.jsdelivr.net/gh/rastikerdar/shabnam-font@v5.0.1/dist/font-face.css'});
    if(/Gandom/i.test(ff)) links.push({id:'nf-gandom', href:'https://cdn.jsdelivr.net/gh/rastikerdar/gandom-font@v1.0.0/dist/font-face.css'});
    if(/Tanha/i.test(ff)) links.push({id:'nf-tanha', href:'https://cdn.jsdelivr.net/gh/rastikerdar/tanha-font@v0.9.0/dist/font-face.css'});
    if(/Estedad/i.test(ff)) links.push({id:'nf-estedad', href:'https://cdn.jsdelivr.net/gh/aminabedi68/Estedad@v7.3/fonts/webfonts/estedad.css'});
    if(/Noto Naskh/i.test(ff) || /Noto Nastaliq/i.test(ff) || /Amiri/i.test(ff) || /Scheherazade/i.test(ff) || /Markazi/i.test(ff) || /Lalezar/i.test(ff) || /Cairo/i.test(ff) || /Tajawal/i.test(ff) || /IBM Plex/i.test(ff)){
      links.push({id:'nf-gfonts', href:'https://fonts.googleapis.com/css2?family=Amiri:wght@400;700&family=Cairo:wght@400;600;700&family=IBM+Plex+Sans+Arabic:wght@400;600;700&family=Lalezar&family=Markazi+Text:wght@400;600;700&family=Noto+Naskh+Arabic:wght@400;600;700&family=Noto+Nastaliq+Urdu:wght@400;600;700&family=Scheherazade+New:wght@400;700&family=Tajawal:wght@400;500;700&display=swap'});
    }
    links.forEach(function(L){
      if(document.getElementById(L.id)) return;
      var link = document.createElement('link');
      link.id = L.id;
      link.rel = 'stylesheet';
      link.href = L.href;
      document.head.appendChild(link);
    });
  }catch(e){ console.warn('font load', e); }
}


function updateBrandLivePreview(){
  try{
    function gv(id, fallback){
      var el = document.getElementById(id);
      if(!el) return fallback;
      if(el.type === 'checkbox') return el.checked;
      return el.value != null ? el.value : fallback;
    }
    try{
      ensureNikanBrandFonts(
        gv('brand-font-title',''),
        gv('brand-font-subtitle',''),
        gv('brand-font-body',''),
        gv('brand-font-announce',''),
        gv('brand-font','')
      );
    }catch(_e){}
    var d = {
      logo: window._brandLogoData || '',
      bgImage: window._brandBgData || '',
      title: gv('brand-title', 'سامانه نیکان'),
      subtitle: gv('brand-subtitle', 'ورود مدارس · مدیر / معاون / معلم'),
      announce: gv('brand-announce', ''),
      ad: gv('brand-ad', ''),
      bg: gv('brand-bg', '#070b14'),
      accent: gv('brand-accent', '#38bdf8'),
      text: gv('brand-text', '#e8eef7'),
      card: gv('brand-card', '#111a2e'),
      fontTitle: gv('brand-font-title', gv('brand-font', 'Tahoma, sans-serif')),
      fontSubtitle: gv('brand-font-subtitle', gv('brand-font', 'Tahoma, sans-serif')),
      fontBody: gv('brand-font-body', gv('brand-font', 'Tahoma, sans-serif')),
      fontAnnounce: gv('brand-font-announce', gv('brand-font', 'Tahoma, sans-serif')),
      titleSize: gv('brand-title-size', '1.65rem'),
      bodySize: gv('brand-body-size', '14.5px'),
      bgOverlay: parseInt(gv('brand-bg-overlay', '55'), 10) || 55
    };

    var root = document.getElementById('brand-live-preview');
    if(!root) return;
    root.style.fontFamily = d.fontBody;
    root.style.fontSize = d.bodySize;
    root.style.color = d.text;

    var bg = document.getElementById('blp-bg');
    if(bg){
      var ov = Math.min(90, Math.max(0, d.bgOverlay)) / 100;
      if(d.bgImage){
        bg.style.backgroundImage = 'linear-gradient(rgba(0,0,0,'+ov+'), rgba(0,0,0,'+ov+')), url("'+d.bgImage+'")';
        bg.style.backgroundSize = 'cover';
        bg.style.backgroundPosition = 'center';
        bg.style.backgroundRepeat = 'no-repeat';
      }else{
        bg.style.backgroundImage = 'radial-gradient(600px 300px at 50% 0%, '+d.accent+'33, transparent 60%), linear-gradient(180deg, '+d.bg+', '+d.bg+')';
        bg.style.backgroundSize = '';
        bg.style.backgroundPosition = '';
      }
    }

    var logo = document.getElementById('blp-logo');
    if(logo){
      if(d.logo){
        logo.innerHTML = '<img src="'+d.logo+'" alt="logo" style="width:100%;height:100%;object-fit:cover;display:block" />';
        logo.style.background = 'transparent';
      }else{
        logo.innerHTML = 'ن';
        logo.style.background = 'linear-gradient(145deg,'+d.accent+','+d.accent+')';
      }
      logo.style.boxShadow = '0 8px 28px '+d.accent+'55';
    }

    var title = document.getElementById('blp-title');
    if(title){
      title.textContent = d.title || 'سامانه نیکان';
      title.style.fontSize = d.titleSize;
      title.style.color = d.text;
      title.style.fontFamily = d.fontTitle;
    }
    var sub = document.getElementById('blp-subtitle');
    if(sub){
      sub.textContent = d.subtitle || '';
      sub.style.color = d.text;
      sub.style.opacity = '0.9';
      sub.style.fontFamily = d.fontSubtitle;
      sub.style.fontSize = d.bodySize;
    }

    var card = document.getElementById('blp-card');
    if(card){
      card.style.background = d.card;
      card.style.borderColor = d.accent + '44';
      card.style.color = d.text;
      card.style.fontFamily = d.fontBody;
      card.style.fontSize = d.bodySize;
    }
    var ct = document.getElementById('blp-card-title');
    if(ct){ ct.style.color = d.accent; ct.style.fontFamily = d.fontBody; }
    var btn = document.getElementById('blp-btn');
    if(btn){
      btn.style.background = 'linear-gradient(135deg,'+d.accent+','+d.accent+')';
      btn.style.fontFamily = d.fontBody;
    }

    var ann = document.getElementById('blp-announce');
    if(ann){
      if(d.announce && String(d.announce).trim()){
        ann.style.display = 'block';
        ann.textContent = d.announce;
        ann.style.background = d.accent + '22';
        ann.style.color = d.accent;
        ann.style.border = '1px solid ' + d.accent + '55';
        ann.style.fontFamily = d.fontAnnounce;
      }else{
        ann.style.display = 'none';
        ann.textContent = '';
      }
    }
    var ad = document.getElementById('blp-ad');
    if(ad){
      if(d.ad && String(d.ad).trim()){
        ad.style.display = 'block';
        ad.textContent = d.ad;
        ad.style.color = d.text;
        ad.style.borderColor = d.accent + '33';
        ad.style.fontFamily = d.fontAnnounce;
      }else{
        ad.style.display = 'none';
        ad.textContent = '';
      }
    }
  }catch(err){ console.warn('preview', err); }
}

function bindBrandLivePreview(){
  try{
    var page = document.getElementById('page-branding');
    if(page && !page._brandDelegated){
      page._brandDelegated = true;
      page.addEventListener('input', function(ev){
        var t = ev.target;
        if(!t || !t.id) return;
        if(String(t.id).indexOf('brand-') === 0) updateBrandLivePreview();
      }, true);
      page.addEventListener('change', function(ev){
        var t = ev.target;
        if(!t || !t.id) return;
        if(String(t.id).indexOf('brand-') === 0) updateBrandLivePreview();
      }, true);
    }
    var ids = ['brand-title','brand-subtitle','brand-announce','brand-ad','brand-ad-link','brand-bg','brand-accent','brand-text','brand-card','brand-font','brand-font-title','brand-font-subtitle','brand-font-body','brand-font-announce','brand-title-size','brand-body-size','brand-bg-overlay','brand-enabled'];
    ids.forEach(function(id){
      var el = document.getElementById(id);
      if(!el) return;
      if(!el._brandPrevBound){
        el._brandPrevBound = true;
        el.addEventListener('input', updateBrandLivePreview);
        el.addEventListener('change', updateBrandLivePreview);
        el.addEventListener('keyup', updateBrandLivePreview);
      }
    });
    updateBrandLivePreview();
  }catch(err){ console.warn('bind preview', err); }
}


async function saveBranding(){
  toast('در حال ارسال ظاهر ورود به سرور...');
  try{
    var payload = collectBrandForm();
    if((payload.logo || '').length > 450000){
      toast('لوگو خیلی بزرگ است');
      return;
    }
    if((payload.bgImage || '').length > 900000){
      toast('عکس پس‌زمینه خیلی بزرگ است');
      return;
    }
    await apiFetch('/api/branding', {
      method: 'PUT',
      body: Object.assign({}, payload, { _motherPanel: true, _compatNoAuth: true }),
      retries: 2,
      timeoutMs: 45000
    });
    try{
      localStorage.setItem('nikan_branding', JSON.stringify(Object.assign({}, payload, { ts: Date.now() })));
    }catch(_e){}
    toast('ظاهر ورود برای همه مدارس ذخیره شد ✓');
    var st = document.getElementById('brand-status');
    if(st) st.textContent = 'ذخیره شد — مدارس با باز کردن مجدد صفحه ورود می‌بینند.';
  }catch(err){
    console.error(err);
    toast('خطا در ذخیره: ' + (err && err.message ? err.message : err));
  }
}

