        if(d.theme)schoolData.theme=d.theme;
        if(d.disciplineTypes)schoolData.disciplineTypes=d.disciplineTypes;
        schoolData._cloudUpdatedAtMs=d.updatedAtMs||(data&&data.updatedAt)||Date.now();
        schoolData._localDirtyAt=0;
        try{localStorage.setItem(dataKey(),JSON.stringify(schoolData))}catch(e){}
