    const rStruct=((d.classes||[]).length+(d.students||[]).length+(d.staff||[]).length+(d.assignments||[]).length);
    const lStruct=((schoolData.classes||[]).length+(schoolData.students||[]).length+(schoolData.staff||[]).length+(schoolData.assignments||[]).length);
    // اگر سرور ریست کرده یا خالی‌سازی عمدی — همیشه بپذیر، داده محلی را برنگردان
