            provider:rem.provider||loc.provider||'melipayamak',
            username:rem.username||loc.username||'',
            password:rem.password||loc.password||'',
            sender:rem.sender||loc.sender||'',
            apiUrl:rem.apiUrl||loc.apiUrl||'',
            updatedAtMs:rem.updatedAtMs||Date.now()
