/** —— گزارش زنگ‌به‌زنگ: کدام کلاس حضور نفرستاده —— */
function parseTimeToMinutes(t){
  if(!t)return null;
  var s=String(t).replace(/[^\\d:]/g,'');
  var p=s.split(':');
  if(p.length<2)return null;
  var h=parseInt(p[0],10), m=parseInt(p[1],10);
  if(isNaN(h)||isNaN(m))return null;
  return h*60+m;
}
function nowMinutesLocal(){
  var d=new Date();
  return d.getHours()*60+d.getMinutes();
}
function managedClassesToday(){
  var list=typeof classesForRole==='function'?classesForRole():(schoolData.classes||[]);
  return (list||[]).filter(function(c){return c&&c.id&&canAccessClass(c.id)});
}
function buildPeriodAttendanceReport(dateIso){
  dateIso=dateIso||todayStr();
  var dow=new Date(dateIso+'T12:00:00').getDay();
  var classes=managedClassesToday();
  var classMap={};
  classes.forEach(function(c){classMap[String(c.id)]=c});
  var classIds={};
  classes.forEach(function(c){classIds[String(c.id)]=true});

  var slots=[];
  (schoolData.assignments||[]).forEach(function(a){
    if(!a||!a.classId)return;
    if(!classIds[String(a.classId)])return;
    var ad=a.dayOfWeek;
    if(ad===''||ad==null||typeof ad==='undefined')return;
    if(parseInt(ad,10)!==dow)return;
    slots.push(a);
  });

  var deleted={};
  (schoolData.deletedSubmissionIds||[]).forEach(function(id){if(id)deleted[String(id)]=true});
  var subsToday=(schoolData.submissions||[]).filter(function(s){
    if(!s||!s.classId||!s.id)return false;
    if(deleted[String(s.id)])return false;
    if(!classIds[String(s.classId)])return false;
    var d=normalizeDateToIso(s.date)||s.date;
    return d===dateIso;
  });

  function normPeriod(p){return String(p||'').trim().replace(/\\s+/g,' ');}
  function normTime(t){
    if(!t)return '';
    var s=String(t).replace(/[^\\d:]/g,'');
    var p=s.split(':');
    if(p.length<2)return s;
    var h=parseInt(p[0],10), m=parseInt(p[1],10);
    if(isNaN(h))return s;
    if(isNaN(m))m=0;
    return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');
  }
  function slotSent(a){
    var pn=normPeriod(a.periodName);
    var st=normTime(a.startTime);
    return subsToday.some(function(s){
      if(String(s.classId)!==String(a.classId))return false;
      if(a.id&&s.assignId&&String(s.assignId)===String(a.id))return true;
      var sp=normPeriod(s.periodName);
      if(pn&&sp&&pn===sp)return true;
      var sst=normTime(s.startTime);
      if(st&&sst&&st===sst)return true;
      if(pn&&sp&&(sp.indexOf(pn)>=0||pn.indexOf(sp)>=0))return true;
      return false;
    });
  }

  // گروه فقط بر اساس ساعت شروع (مثلاً 07:15)
  var groups={};
  slots.forEach(function(a){
    var st=normTime(a.startTime)||'بدون‌ساعت';
    var key=st;
    if(!groups[key]){
      groups[key]={
        periodName:'شروع '+st,
        startTime:st==='بدون‌ساعت'?'':st,
        endTime:'',
        startMin:parseTimeToMinutes(st==='بدون‌ساعت'?'':st),
        slots:[],
        sent:[],
        missing:[]
      };
    }
    // endTime: آخرین پایان در این ساعت
    if(a.endTime){
      var em=parseTimeToMinutes(a.endTime);
      var cur=parseTimeToMinutes(groups[key].endTime);
      if(em!=null&&(cur==null||em>cur))groups[key].endTime=normTime(a.endTime);
    }
    groups[key].slots.push(a);
    var c=classMap[String(a.classId)];
    var t=(schoolData.staff||[]).find(function(x){return x&&String(x.id)===String(a.teacherId)});
    var row={
      assignId:a.id,
      classId:a.classId,
      className:c?(typeof classTitle==='function'?classTitle(c):(c.name||'?')):String(a.classId),
      teacherName:t?(t.name||t.username||''):(a.teacherName||''),
      subject:a.subject||'',
      periodName:normPeriod(a.periodName),
      shift:c?c.shift:null
    };
    if(slotSent(a))groups[key].sent.push(row);
    else groups[key].missing.push(row);
  });

  var scheduledClass={};
  slots.forEach(function(a){scheduledClass[String(a.classId)]=true});
  var noScheduleToday=classes.filter(function(c){return !scheduledClass[String(c.id)]});

  var periods=Object.keys(groups).map(function(k){return groups[k]});
  periods.sort(function(a,b){
    var am=a.startMin!=null?a.startMin:9999;
    var bm=b.startMin!=null?b.startMin:9999;
    if(am!==bm)return am-bm;
    return String(a.startTime).localeCompare(String(b.startTime));
  });

  var nowM=nowMinutesLocal();
  var isToday=(dateIso===todayStr());
  periods.forEach(function(p){
    if(!isToday){p.phase='past';return;}
    if(p.startMin==null){p.phase='current';return;}
    if(nowM<p.startMin)p.phase='upcoming';
    else if(p.endTime&&parseTimeToMinutes(p.endTime)!=null&&nowM>parseTimeToMinutes(p.endTime)+20)p.phase='past';
    else p.phase='current';
  });

  return {
    date:dateIso,
    dow:dow,
    dayName:(typeof DAYS!=='undefined'?DAYS[dow]:'')||'',
    periods:periods,
    noScheduleToday:noScheduleToday,
    totalClasses:classes.length,
    totalSlots:slots.length,
    totalAssignAll:(schoolData.assignments||[]).length,
    subsToday:subsToday.length
  };
}


/** —— صفحه پیگیری ارسال حضور (تب جدا) —— */
function ptParseDateInput(){
  var el=document.getElementById('pt-date');
  var raw=el?(el.value||'').trim():'';
  if(typeof toEnDigits==='function')raw=toEnDigits(raw);
  if(!raw)return todayStr();
  var iso=typeof normalizeDateToIso==='function'?normalizeDateToIso(raw):'';
  return iso||todayStr();
}
function ptSetToday(){
  var el=document.getElementById('pt-date');
  if(el)el.value=typeof formatDateFa==='function'?formatDateFa(todayStr()):todayStr();
  var fa=document.getElementById('pt-date-fa');
  if(fa)fa.textContent='امروز';
  renderPeriodTrack();
}
function ptShiftDay(delta){
  var iso=ptParseDateInput();
  var d=new Date(iso+'T12:00:00');
  if(isNaN(d.getTime()))d=new Date();
  d.setDate(d.getDate()+(delta||0));
  var y=d.getFullYear(), m=d.getMonth()+1, day=d.getDate();
  var iso2=y+'-'+String(m).padStart(2,'0')+'-'+String(day).padStart(2,'0');
  var el=document.getElementById('pt-date');
  if(el)el.value=typeof formatDateFa==='function'?formatDateFa(iso2):iso2;
  renderPeriodTrack();
}
function renderPeriodTrack(){
  var out=document.getElementById('period-track-out');
  if(!out)return;
  if(!canManage()){out.innerHTML='<p class="hint">فقط مدیر و معاون</p>';return;}
  try{
    var iso=ptParseDateInput();
    var el=document.getElementById('pt-date');
    if(el&&!el.value)el.value=typeof formatDateFa==='function'?formatDateFa(iso):iso;
    var fa=document.getElementById('pt-date-fa');
    if(fa){
      var dn=(typeof DAYS!=='undefined'?DAYS[new Date(iso+'T12:00:00').getDay()]:'')||'';
      fa.textContent=dn+' · '+formatDateFa(iso)+(iso===todayStr()?' (امروز)':'');
    }
    var rep=buildPeriodAttendanceReport(iso);
    var html='';
    html+='<p class="hint">برنامه این روز: <b>'+(rep.totalSlots||0)+'</b> · ارسال ثبت‌شده: <b>'+(rep.subsToday||0)+'</b></p>';
    if(!rep.periods.length){
      html+='<p class="hint">برای این تاریخ زنگ/ساعت شروعی در برنامه نیست. روز هفته برنامه را چک کنید.</p>';
      out.innerHTML=html;
      return;
    }
    rep.periods.forEach(function(p){
      var total=p.slots.length, sentN=p.sent.length, missN=p.missing.length;
      var phaseFa={upcoming:'هنوز شروع نشده',current:'بعد از شروع',past:'گذشته'}[p.phase]||'';
      var border=missN&&(p.phase==='current'||p.phase==='past'||iso!==todayStr())?'border:1px solid rgba(248,113,113,.5);':'border:1px solid var(--line);';
      html+='<div style="margin:12px 0;padding:12px;border-radius:12px;'+border+'">';
      html+='<strong style="color:var(--blue)">ساعت '+(p.startTime||'?');
      if(p.endTime)html+=' تا '+p.endTime;
      html+='</strong>';
      if(iso===todayStr()&&phaseFa)html+=' <span class="badge">'+phaseFa+'</span>';
      html+='<div class="meta" style="margin-top:6px">در برنامه: <b>'+total+'</b> · فرستاده: <b style="color:var(--green)">'+sentN+'</b> · نفرستاده: <b style="color:'+(missN?'var(--red)':'var(--green)')+'">'+missN+'</b></div>';
      if(missN){
        html+='<div style="margin-top:8px"><div class="meta" style="color:var(--red);font-weight:700">بدون ارسال:</div>';
        p.missing.forEach(function(r){
          html+='<div class="list-item" style="padding:6px 0"><div><div class="name">'+r.className+'</div><div class="meta">'+(r.teacherName?('معلم: '+r.teacherName):'')+(r.subject?(' · '+r.subject):'')+(r.periodName?(' · '+r.periodName):'')+'</div></div><span class="status-p">نفرستاده</span></div>';
        });
        html+='</div>';
      }else{
        html+='<p class="hint" style="color:var(--green);margin-top:6px">✓ همه ارسال کرده‌اند</p>';
      }
      if(sentN&&missN){
        html+='<details style="margin-top:6px"><summary class="hint" style="cursor:pointer">ارسال‌شده‌ها ('+sentN+')</summary>';
        p.sent.forEach(function(r){html+='<div class="meta">✓ '+r.className+(r.teacherName?(' · '+r.teacherName):'')+'</div>';});
        html+='</details>';
      }
      html+='</div>';
    });
    if(rep.noScheduleToday&&rep.noScheduleToday.length){
      html+='<p class="hint">کلاس بدون برنامه این روز: '+rep.noScheduleToday.map(function(c){return classTitle(c)}).join('، ')+'</p>';
    }
    out.innerHTML=html;
  }catch(e){
    console.warn('renderPeriodTrack',e);
    out.innerHTML='<p class="hint">خطا: '+(e&&e.message?e.message:e)+'</p>';
  }
}

