function parseFaDateInput(s){
  // خروجی همیشه YYYY-MM-DD میلادی تا با attendance.date یکی باشد
  return normalizeDateToIso(s);
}
/** آیا این رکورد حضور متعلق به معلم فعلی است؟ */
function isMyTeacherAttendance(a){
  if(!a)return false;
  if(!isTeacher()||!userSession)return true;
  var myIds={};
  if(userSession.staffId)myIds[String(userSession.staffId)]=true;
  if(userSession.id)myIds[String(userSession.id)]=true;
  if(!Object.keys(myIds).length)return true;
  // صریح teacherId روی رکورد
  if(a.teacherId)return !!myIds[String(a.teacherId)];
  // از طریق submission
  if(a.submissionId){
    var sub=(schoolData.submissions||[]).find(function(x){return x.id===a.submissionId});
    if(sub&&sub.teacherId)return !!myIds[String(sub.teacherId)];
  }
  // حضور معلم بدون شناسه: فقط اگر fromTeacher نباشد (موارد مدیر) را به معلم نشان نده؛
  // موارد fromTeacher بدون submissionId را به معلم فعلی نشان نده تا حضور معلم دیگر لو نرود
  if(a.fromTeacher)return false;
  // موارد دستی مدیر/انضباط — معلم نباید ببیند
  return false;
}
/** حضور/غیبت فقط متعلق به این معلم برای یک دانش‌آموز */
function teacherOwnAttendance(sid,from,to){
  var list=(schoolData.attendance||[]).filter(function(a){
    if(a.studentId!==sid)return false;
    if(a.type!=='absent'&&a.type!=='late')return false;
    return isMyTeacherAttendance(a);
  });
  return filterAttByRange(list,from,to);
}
/** تأخیر ورود صبح (مدیر/معاون) — در عملکرد دانش‌آموز دیده شود */
function deputyMorningLates(sid,from,to){
  var list=(schoolData.attendance||[]).filter(function(a){
    if(a.studentId!==sid)return false;
    if((a.type||'')!=='late')return false;
    if(a.fromTeacher)return false;
    return !!(a.fromManager||a.fromDeputy||(a.note||'').indexOf('تأخیر ورود')>=0||(a.note||'').indexOf('ورود به مدرسه')>=0);
  });
  return filterAttByRange(list,from,to);
}
/** غیبت روزی یکی — فقط از حضور این معلم */
function teacherCountAbsentDays(sid,from,to){
  var days={};
  teacherOwnAttendance(sid,from,to).forEach(function(a){
    if((a.type||'')!=='absent')return;
    var day=normalizeDateToIso(a.date)||String(a.date||'');
    if(day)days[day]=true;
  });
  return Object.keys(days).length;
}
/** تأخیر: هر جلسه/زنگ جدا (چهار زنگ تأخیر = ۴) */
function teacherCountLates(sid,from,to){
  return teacherOwnAttendance(sid,from,to).filter(function(a){return (a.type||'')==='late'}).length;
}
