function openBulkDiscPage(){
  if(!canManage())return toast('فقط مدیر یا معاون');
  var sel=document.getElementById('bulk-disc-class');
  if(sel){
    sel.innerHTML='<option value="">— انتخاب کلاس —</option>'+classesForRole().map(function(c){return '<option value="'+c.id+'">'+classTitle(c)+'</option>'}).join('');
  }
  var typeSel=document.getElementById('bulk-disc-type');
  if(typeSel){
    var types=(schoolData.disciplineTypes||[]).slice();
    if(!types.length)types=[{id:'other',name:'مورد انضباطی',scoreDeduct:1}];
    typeSel.innerHTML=types.map(function(t){return '<option value="'+t.id+'">'+(t.name||t.id)+'</option>'}).join('');
  }
  var d=document.getElementById('bulk-disc-date');
  if(d&&!d.value)try{d.value=formatDateFa(todayStr())}catch(e){}
  var n=document.getElementById('bulk-disc-note');if(n)n.value='';
  var sc=document.getElementById('bulk-disc-score');if(sc)sc.value='';
  bulkDiscTypeChanged();
  loadBulkDiscStudents();
}
function bulkDiscTypeChanged(){
  try{
    var type=(document.getElementById('bulk-disc-type')||{}).value;
    var dt=(schoolData.disciplineTypes||[]).find(function(t){return t&&t.id===type});
    var sc=document.getElementById('bulk-disc-score');
    if(sc&&dt){sc.placeholder=String(dt.scoreDeduct!=null?dt.scoreDeduct:1)}
  }catch(e){}
}
function loadBulkDiscStudents(){
  if(!canManage())return;
  var list=document.getElementById('bulk-disc-list');
  var sel=document.getElementById('bulk-disc-class');
  if(!list||!sel)return;
  var cid=sel.value;
  if(!cid){list.innerHTML='<p class="hint">کلاس را انتخاب کنید</p>';return}
  var stus=(schoolData.students||[]).filter(function(s){return s&&String(s.classId)===String(cid)});
  if(!stus.length){list.innerHTML='<p class="hint">دانش‌آموزی در این کلاس نیست</p>';return}
  list.innerHTML=stus.map(function(s){
    return '<label class="checkbox-row" style="border-bottom:1px solid var(--border);padding:8px 0"><span><input type="checkbox" class="bulk-disc-cb" value="'+s.id+'" checked /> <strong>'+s.name+'</strong>'+(s.group?(' <span class="meta">· گروه '+s.group+'</span>'):'')+'</span></label>';
  }).join('');
}
function bulkDiscSelectAll(on){
  document.querySelectorAll('.bulk-disc-cb').forEach(function(cb){cb.checked=!!on});
}
async function submitBulkDiscipline(){
  if(!canManage())return toast('فقط مدیر یا معاون');
  var cid=(document.getElementById('bulk-disc-class')||{}).value;
  if(!cid)return toast('کلاس را انتخاب کنید');
  var ids=[].slice.call(document.querySelectorAll('.bulk-disc-cb:checked')).map(function(cb){return cb.value}).filter(Boolean);
  if(!ids.length)return toast('حداقل یک دانش‌آموز را انتخاب کنید');
  var type=(document.getElementById('bulk-disc-type')||{}).value||'other';
  var dt=(schoolData.disciplineTypes||[]).find(function(t){return t&&t.id===type});
  var typeLabel=dt?dt.name:(type==='absent'?'غیبت':type==='late'?'تأخیر':type==='escape'?'فرار':'مورد انضباطی');
  var note=((document.getElementById('bulk-disc-note')||{}).value||'').trim();
  if(!note)note=typeLabel+' (ثبت گروهی)';
  var scoreRaw=((document.getElementById('bulk-disc-score')||{}).value||'').trim();
  if(typeof toEnDigits==='function')scoreRaw=toEnDigits(scoreRaw);
  var deduct;
  if(scoreRaw!==''){
    deduct=parseFloat(scoreRaw);
    if(isNaN(deduct))return toast('کسر نمره نامعتبر است');
  }else if(dt&&dt.scoreDeduct!=null&&!isNaN(parseFloat(dt.scoreDeduct))){
    deduct=parseFloat(dt.scoreDeduct);
  }else if(type==='absent'){
    deduct=(schoolData.rules&&schoolData.rules.absent)!=null?parseFloat(schoolData.rules.absent):0.5;
  }else if(type==='late'){
    deduct=(schoolData.rules&&schoolData.rules.late)!=null?parseFloat(schoolData.rules.late):0.25;
  }else if(type==='escape'){
    deduct=(schoolData.rules&&schoolData.rules.escape)!=null?parseFloat(schoolData.rules.escape):1;
  }else{
    deduct=1;
  }
  if(isNaN(deduct))deduct=0;
  var dateRaw=((document.getElementById('bulk-disc-date')||{}).value||'').trim();
  var day=dateRaw?(typeof normalizeDateToIso==='function'?normalizeDateToIso(dateRaw):dateRaw):todayStr();
  if(!Array.isArray(schoolData.attendance))schoolData.attendance=[];
  var n=0;
  ids.forEach(function(sid){
    var s=(schoolData.students||[]).find(function(x){return x&&x.id===sid});
    if(!s)return;
    schoolData.attendance.push({
      id:uid(),
      studentId:sid,
      classId:s.classId||cid,
      date:day,
      type:type||'other',
      typeName:typeLabel,
      note:note,
      scoreDeduct:deduct,
      scoreLocked:true,
      fromDiscipline:true,
      fromManager:true,
      bulkGroup:true,
      createdAtMs:Date.now()
    });
    n++;
  });
  if(!n)return toast('دانش‌آموزی ثبت نشد');
  schoolData._cloudUpdatedAtMs=Date.now();
  schoolData._localDirtyAt=Date.now();
  saveSchoolData();
  toast('ثبت محلی '+n+' نفر · '+typeLabel+' · کسر '+deduct+' — ارسال به سرور…');
  try{
    var just=(schoolData.attendance||[]).filter(function(a){return a&&a.fromDiscipline&&a.bulkGroup&&a.createdAtMs&&(Date.now()-a.createdAtMs)<60000}).slice(-n);
    if(just.length<n){
      just=(schoolData.attendance||[]).filter(function(a){return a&&a.fromDiscipline}).slice(-n);
    }
    var ok=await pushSoftAttendanceRecords(just,{retries:3,timeoutMs:60000});
    if(ok)toast('ثبت گروهی روی سرور: '+n+' نفر · '+typeLabel+' · کسر '+deduct,4000);
    else toast('محلی ذخیره شد — ارسال به سرور را بزنید',4000);
  }catch(e){
    toast('محلی ذخیره شد — ارسال ناموفق',4000);
  }
}


window._discPhotos=[];
function pickDiscPhoto(mode){
  try{
    var input=document.createElement('input');
    input.type='file';
    input.accept='image/*';
    if(mode==='camera')input.setAttribute('capture','environment');
    input.style.cssText='position:fixed;left:0;top:0;width:1px;height:1px;opacity:0.01;z-index:99999';
    input.onchange=function(){
      var f=input.files&&input.files[0];
      try{if(input.parentNode)input.parentNode.removeChild(input)}catch(e){}
      if(!f)return;
      toast('فشرده‌سازی عکس…');
      compressPhoto(f, 1100, function(url){
        if(!url){toast('پردازش عکس ناموفق');return}
        if(!Array.isArray(window._discPhotos))window._discPhotos=[];
        window._discPhotos.push(url);
        renderDiscPhotoThumbs();
        toast('عکس اضافه شد');
      }, {quality:0.82, maxBytes:420000, minQuality:0.68});
    };
    document.body.appendChild(input);
    input.click();
  }catch(e){toast('باز کردن عکس ممکن نشد')}
}
function renderDiscPhotoThumbs(){
  var box=document.getElementById('d-photo-thumbs');
  if(!box)return;
  var arr=window._discPhotos||[];
  if(!arr.length){box.innerHTML='';return}
  box.innerHTML=arr.map(function(ph,i){
    return '<div style="position:relative;width:72px"><img src="'+ph+'" style="width:72px;height:72px;object-fit:cover;border-radius:8px;border:1px solid var(--line)"/><button type="button" class="btn btn-danger btn-sm" style="position:absolute;top:2px;left:2px;padding:2px 6px;font-size:11px" onclick="window._discPhotos.splice('+i+',1);renderDiscPhotoThumbs()">×</button></div>';
  }).join('');
}
