          body.replaceAssignments = false;
          body.clearAssignments = false;
          body.clearStructure = false;
          body.resetYear = false;
          body.clearPerformance = false;
          body.structureWriteToken = false;
          body.managerAuthority = false;
          body.confirmStructureWrite = null;
