          exams: Array.isArray(body.exams) ? mergeById(prev.exams, body.exams) : (prev.exams || []),
          messages: Array.isArray(body.messages) ? mergeById(prev.messages, body.messages) : (prev.messages || []),
          absentSmsSent: Object.assign({}, prev.absentSmsSent || {}, body.absentSmsSent || {}),
