                if (old) {
                  const incPass = (x.pass != null && String(x.pass) !== '') ? x.pass : ((x.password != null && String(x.password) !== '') ? x.password : '');
                  if (!incPass) {
                    if (old.pass) merged.pass = old.pass;
                    if (old.password) merged.password = old.password;
                  }
                  if (!(x.photo || x.image) && (old.photo || old.image)) {
                    merged.photo = old.photo || '';
                    if (old.image) merged.image = old.image;
                  }
                }
                map[String(x.id)] = merged;
